text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Hi! Thanks for contacting Nimbus Telecom. I'm Ravi. How can I help you today? 😊",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hey Ravi. I'm really fed up with the constant drops in my connection. It's making it impossible to work from home.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I'm sorry to hear that you've been having trouble with your connection. I know how frustrating that is when you're working.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "agent",
      "text": "Before we look into this, could you please provide your account number and date of birth for verification?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Sure. Account number is 42809053 and my DOB is 09/09/1977.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you, James Nair. I see your account here. Let me check the line status.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "I've already called three times this month. I'm just done. I want to cancel my service and switch to another provider.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "I'm sorry you feel that way. I can certainly help you with the cancellation process.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Just do it. I'm not paying for something that doesn't work. 😡",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will process the cancellation request for your account now.",
      "tags": [
        "action:cancellation_or_retention"
      ]
    },
    {
      "speaker": "customer",
      "text": "This is ridiculous. Why is it so hard to get a stable connection? I'm so angry right now.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I understand your frustration. However, since this is a request for a full account closure, I need to escalate this to my supervisor for final approval.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Are you kidding me? I just want to leave! This is the worst service ever!!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I apologize for the inconvenience. Is there anything else I can help you with today? I've sent the request to the supervisor, and they will contact you. Goodbye!",
      "tags": [
        "closure"
      ]
    }
  ]
}
